-- Historical recovery only. Do not apply to an existing production database.
-- Original recorded version: 20260814204404
create table if not exists public.education_benchmark_systems (
  country_code text primary key,
  country_name text not null,
  region text not null,
  benchmark_type text not null,
  strengths text[] not null default '{}',
  transferable_lessons text[] not null default '{}',
  cautions text[] not null default '{}',
  evidence_note text,
  active boolean not null default true,
  updated_at timestamptz not null default now()
);
alter table public.education_benchmark_systems enable row level security;
drop policy if exists benchmark_systems_read on public.education_benchmark_systems;
create policy benchmark_systems_read on public.education_benchmark_systems for select to authenticated using (true);
revoke all on public.education_benchmark_systems from anon;
grant select on public.education_benchmark_systems to authenticated,service_role;

insert into public.education_benchmark_systems(country_code,country_name,region,benchmark_type,strengths,transferable_lessons,cautions,evidence_note) values
('SG','Singapore','Asia','high_performance',array['mastery and strong fundamentals','coherent curriculum and assessment','systematic teacher development','continuous improvement'],array['mastery-before-acceleration','clear competency progressions','teacher professional learning loops'],array['avoid excessive exam pressure','adapt to Ethiopian class size and resource constraints'],'PISA 2022 global leader across mathematics, reading and science.'),
('JP','Japan','Asia','high_performance',array['strong fundamentals','lesson study and collaborative teacher improvement','student responsibility and routines','resilient outcomes'],array['teacher lesson-study communities','daily learning routines','whole-child responsibility'],array['do not copy long-hours culture','localize routines to Ethiopian schools'],'PISA 2022 high performance and resilience.'),
