('EE','Estonia','Europe','high_performance_digital',array['high equity','digital competence','teacher and school autonomy','broad curriculum'],array['digital-by-design learning','teacher autonomy with accountability','problem solving and digital literacy'],array['technology must support pedagogy, not replace it'],'Europe-leading PISA performance and high school autonomy.'),
