('PL','Poland','Europe','improvement_and_rigor',array['strong core curriculum','low grade repetition','school autonomy','historical rapid improvement'],array['clear standards','delay failure and provide support','principal/teacher responsibility'],array['recent declines show reforms require stability and wellbeing'],'PISA 2022 remained above OECD average despite recent decline.'),
