('AU','Australia','Oceania','high_performance_standards',array['national learning standards','general capabilities','school data and assessment','diverse pathways'],array['common competency framework','critical thinking and communication across subjects','school outcome dashboards'],array['avoid excessive testing and reporting burden'],'PISA 2022 above OECD average across core domains.'),
('NZ','New Zealand','Oceania','high_performance_culturally_responsive',array['local curriculum flexibility','culturally responsive learning','student agency','project learning'],array['local-context projects','community knowledge','learner voice'],array['preserve consistent mastery standards while allowing local flexibility'],'PISA 2022 above OECD average in core areas with sampling cautions noted by OECD.'),
('NL','Netherlands','Europe','pathway_differentiation',array['multiple secondary pathways','strong vocational routes','school choice and autonomy','early career orientation'],array['clear academic and vocational route maps','transition guidance','pathway transparency'],array['avoid premature sorting that locks learners into paths'],'Benchmark used mainly for differentiated academic/vocational pathway design.'),
('PT','Portugal','Europe','sustained_improvement',array['sustained improvement over prior decades','student belonging','teacher material autonomy','inclusion'],array['continuous system improvement','belonging and safety metrics','reduce repetition through support'],array['grade repetition remains relatively high and should not be copied'],'PISA 2022 close to OECD average with strong belonging indicators and historical improvement.'),
