('UY','Uruguay','Latin America','digital_equity_innovation',array['universal digital access','teacher digital training','national learning platform','equity-focused technology'],array['Mela Lite and device/access strategy','teacher training with technology','national-scale platform thinking'],array['devices alone do not guarantee learning; pair access with pedagogy and teacher support'],'Plan Ceibal evolved from one-device access into a broader digital education ecosystem.')
on conflict (country_code) do update set country_name=excluded.country_name,region=excluded.region,benchmark_type=excluded.benchmark_type,strengths=excluded.strengths,transferable_lessons=excluded.transferable_lessons,cautions=excluded.cautions,evidence_note=excluded.evidence_note,active=true,updated_at=now();

create table if not exists public.mela_education_engines (
  engine_key text primary key,
  title text not null,
  purpose text not null,
  benchmark_countries text[] not null default '{}',
  stage_keys text[] not null default '{}',
  target_outcomes text[] not null default '{}',
  implementation_status text not null default 'planned' check (implementation_status in ('implemented','partial','foundation','planned','provider_gated','human_review')),
  current_assets jsonb not null default '{}'::jsonb,
  display_order smallint not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.mela_education_engines enable row level security;
drop policy if exists mela_education_engines_read on public.mela_education_engines;
create policy mela_education_engines_read on public.mela_education_engines for select to authenticated using (true);
revoke all on public.mela_education_engines from anon;
grant select on public.mela_education_engines to authenticated,service_role;

insert into public.mela_education_engines(engine_key,title,purpose,benchmark_countries,stage_keys,target_outcomes,implementation_status,current_assets,display_order) values
('mastery','Mela Mastery Engine','Know exactly what each learner has mastered, what is developing, and what needs support.',array['SG','VN','FI','IE'],array['school_1_6','school_7_8','school_9_10','school_11_12','college_tvet','university'],array['foundational mastery','reduced hidden learning gaps','evidence-based progression'],'implemented',jsonb_build_object('tables',array['learning_competencies','learner_mastery_records','learner_mastery_evidence'],'rpc','get_my_mastery_engine'),10),
('passport','Mela Learner Passport','One evolving record from foundational learning through transition, verified skills, projects and work.',array['EE','CA','AU','NZ'],array['school_1_6','school_7_8','school_9_10','school_11_12','college_tvet','university'],array['portable learner evidence','continuity across stages','less dependence on one exam'],'partial',jsonb_build_object('existing','Career Passport and mastery evidence','next','stage-specific passport views'),20),
('diagnostic_catchup','Mela Diagnostic & Catch-Up','Diagnose actual competency level and build a short targeted recovery plan instead of assuming grade equals mastery.',array['SG','VN','FI','PT'],array['school_1_6','school_7_8','school_9_10','school_11_12'],array['learning recovery','foundational literacy/numeracy','reduced repetition'],'foundation',jsonb_build_object('uses','learning_competencies and mastery evidence','next','adaptive diagnostics and catch-up plans'),30),
('teacher_copilot','Mela Teacher Copilot','Strengthen teachers with lesson planning, differentiation, formative assessment, intervention signals and five-language support.',array['JP','EE','FI','VN','IE'],array['school_1_6','school_7_8','school_9_10','school_11_12','college_tvet','university'],array['teacher effectiveness','faster intervention','lower preparation burden'],'foundation',jsonb_build_object('principle','teacher-in-the-loop; never teacher replacement'),40),
('projects_impact','Mela Projects & Impact','Turn learning into projects, community contribution and demonstrated capability.',array['EE','DK','NZ','AU'],array['school_1_6','school_7_8','school_9_10','school_11_12','college_tvet','university'],array['problem solving','creativity','community contribution','portfolio evidence'],'partial',jsonb_build_object('existing','learner project competencies','next','stage-safe project and impact rubrics'),50),
('mela_next','Mela Next','Guide learners from Grade 9 onward through subject choices, Grade 12 transition, TVET, university, scholarships and careers.',array['CH','NL','KR','CZ'],array['school_9_10','school_11_12','college_tvet','university'],array['better transitions','pathway clarity','reduced dead ends'],'partial',jsonb_build_object('existing','Opportunity Graph, scholarships, Career Coach','next','visual transition planner'),60),
('opportunity_graph','Mela Opportunity Graph','Connect competencies and pathways to real scholarships, placements, jobs, projects and employer demand.',array['CH','NL','SG','KR'],array['school_11_12','college_tvet','university'],array['education-to-opportunity alignment','skills-demand feedback','transparent next steps'],'implemented',jsonb_build_object('tables',array['opportunity_graph_nodes','opportunity_graph_edges'],'rpc','get_my_opportunity_graph'),70),
('family_support','Mela Family','Give guardians simple, respectful learning-progress information and offline activities without surveillance.',array['FI','SG','PT','CA'],array['school_1_6','school_7_8','school_9_10','school_11_12'],array['family engagement','early support','learner safety'],'foundation',jsonb_build_object('existing','guardian verification workflow','next','family progress summaries and offline activities'),80),
('institution_outcomes','Mela Outcomes','Give schools, TVETs, universities and partners actionable learning, transition and placement outcomes instead of vanity metrics.',array['AU','EE','IE','VN'],array['school_1_6','school_7_8','school_9_10','school_11_12','college_tvet','university'],array['learning improvement','intervention visibility','placement outcomes','system feedback'],'planned',jsonb_build_object('principle','measure mastery and progression, not video views'),90),
('mela_lite','Mela Lite','Design for low bandwidth, intermittent connectivity and equitable access from the beginning.',array['UY','EE','VN'],array['school_1_6','school_7_8','school_9_10','school_11_12','college_tvet','university'],array['access equity','offline continuity','regional reach'],'planned',jsonb_build_object('next','text-first pages, download packs, offline practice and sync'),100)
on conflict (engine_key) do update set title=excluded.title,purpose=excluded.purpose,benchmark_countries=excluded.benchmark_countries,stage_keys=excluded.stage_keys,target_outcomes=excluded.target_outcomes,implementation_status=excluded.implementation_status,current_assets=excluded.current_assets,display_order=excluded.display_order,updated_at=now();

create or replace function public.get_mela_benchmark_blueprint()
returns jsonb language sql stable security invoker set search_path=''
as $function$ select jsonb_build_object('systems',(select coalesce(jsonb_agg(to_jsonb(b) order by b.country_name),'[]'::jsonb) from public.education_benchmark_systems b where b.active),'engines',(select coalesce(jsonb_agg(to_jsonb(e) order by e.display_order),'[]'::jsonb) from public.mela_education_engines e)); $function$;
revoke all on function public.get_mela_benchmark_blueprint() from public,anon;
grant execute on function public.get_mela_benchmark_blueprint() to authenticated,service_role;
;
